// Builds the fragments worker as ONE self-contained classic script and writes it, base64, to
// src/generated/fragments-worker.ts (git-ignored; regenerated by `npm run dev|build|publish` and on install).
//
// Why: @thatopen-platform/fragments-beta 3.5.9 (2026-09-23) ships a broken `./inline` entry — its embedded
// worker is a 354-byte stub that imports "./fragments-thread-*.js", which cannot resolve from a blob URL, so
// the worker dies with "Cannot use import statement outside a module" and every model load hangs. 3.5.8
// embedded the full bundled worker (≈1.4 MB, no imports). This does what their generate-inline-worker step
// should have done, from the installed version's own Worker/worker.mjs, so the worker always matches the
// main-thread engine. Delete this (and use `import "@thatopen/fragments/inline"`) once a fixed beta ships.
import { build } from "esbuild";
import { mkdirSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const entry = join(root, "node_modules", "@thatopen-platform", "fragments-beta", "dist", "Worker", "worker.mjs");
const out = join(root, "src", "generated", "fragments-worker.ts");

if (!existsSync(entry)) {
  // Stable engine (no beta package): the app does not use a generated worker there.
  console.log("[fragments-worker] beta fragments not installed — skipped");
  process.exit(0);
}

const result = await build({
  entryPoints: [entry],
  bundle: true,       // folds fragments-thread-*.js and the lazy meshopt/streamed chunks into this one file
  format: "iife",     // a classic worker script: no import/export statements left
  platform: "browser",
  target: "es2020",
  minify: true,
  write: false,
  logLevel: "warning",
});
const code = result.outputFiles[0].text;
if (/^\s*import[\s{*]/m.test(code) || /^\s*export[\s{]/m.test(code)) throw new Error("fragments worker still has import/export statements");

mkdirSync(dirname(out), { recursive: true });
writeFileSync(out,
  "// GENERATED by scripts/build-fragments-worker.mjs — do not edit, do not commit.\n" +
  `export const FRAGMENTS_WORKER_B64 = "${Buffer.from(code, "utf8").toString("base64")}";\n`);
console.log(`[fragments-worker] wrote ${out} (${code.length} bytes of worker code)`);
